MultiLanguageSpellData['mx'][465999] = {name = "Gruñidora blindada carmesí", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Algunos goblins llaman cariñosamente a sus hienas \"gruñidoras\". A esta le gusta excavar.\"\nVendedor:\nRocco Razzbum\nZona:\nMinahonda\nCosto:\n8125"}
MultiLanguageSpellData['mx'][466000] = {name = "Compactadente mechaoscura", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"La madre de todas las hienas de basural de Stix. Sus mandíbulas son capaces de destrozar cualquier cosa (o cualquier persona) de la que Gallywix quiera deshacerse.\"\nVendedor:\nAndo, el Gatillero\nZona:\nLiberación de Minahonda\nCosto:\n500"}
MultiLanguageSpellData['mx'][466001] = {name = "Aplastahuesos Aguasnegras", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Es mejor que guardes esos huesos si no quieres que los aplasten.\"\nBotín:\nTesoro de Aguasnegras\nZona:\nMinahonda"}
MultiLanguageSpellData['mx'][466002] = {name = "Gruñidora blindada violeta", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Smaks sabe un par de cosas del cuidado de las hienas. Regla número uno: ¡no acerques los dedos a esos dientes!\"\nVendedor:\nSmaks Birlatope\nZona:\nMinahonda\nCosto:\n8125"}
MultiLanguageSpellData['mx'][466006] = {name = "Montón de basura grande", additional_info = nil}
MultiLanguageSpellData['mx'][466007] = {name = "Caparabomba", additional_info = "Instante\n[q]Las bombas reptantes usan un revestimiento para bombas protector que reduce un 99% todo el daño que reciben.\n\n Explotan solo cuando entran en contacto con su objetivo e infligen 300 p. de daño de fuego a los jugadores que están en un radio de 5 m."}
MultiLanguageSpellData['mx'][466011] = {name = "Fogorrex, el Furioso", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Ser el VIP más importante de todos en el Gallagio tiene sus beneficios, y uno son las llaves de este antiguo Rey de la matanza. ¡Gracias a la tecnología goblin de vanguardia, puede recorrer más de 25 metros por litro!\"\nVendedor:\nAndo, el Gatillero\nZona:\nLiberación de Minahonda\nCosto:\n777"}
MultiLanguageSpellData['mx'][466012] = {name = "Cohetoide fallido", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Recuperado de las gradas del Caldero durante un enfrentamiento particularmente cruento. Cuando le preguntaron si fue un error que no haya explotado, el operador de Torq solo respondió: \"Es probable\".\"\nVendedor:\nAndo, el Gatillero\nZona:\nLiberación de Minahonda\nCosto:\n500"}
MultiLanguageSpellData['mx'][466013] = {name = "Cohete de entrega ocre", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"¡Para llevar paquetes y pasajeros del punto A al punto B con estilo!\"\nVendedor:\nShredz, el Chatarrero\nZona:\nMinahonda\nCosto:\n11375"}
MultiLanguageSpellData['mx'][466014] = {name = "Benefactor Bonvapor", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"¡Te ofrece un viaje rápido o una gran explosión para tus enemigos!\"\nBotín:\nTesoro de Bonvapor\nZona:\nMinahonda"}
MultiLanguageSpellData['mx'][466016] = {name = "El especial de Birlatope", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Smaks está seguro de que este cohete no explotará en pleno vuelo. Absolutamente. Sin duda. 100%. Garantizado.\"\nVendedor:\nSmaks Birlatope\nZona:\nMinahonda\nCosto:\n11375"}
MultiLanguageSpellData['mx'][466017] = {name = "Investigador de innovaciones", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Cuando el mejor camino hacia una buena idea es ir muy rápido.\"\nVendedor:\nSkedgit Ceniestallidos\nZona:\nMinahonda\nCosto:\n25"}
MultiLanguageSpellData['mx'][466018] = {name = "Machacadora mechaoscura", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Excelente para ensuciar cosas. No tan bueno para limpiarlas.\"\nVendedor:\nSitch Nefasio\nZona:\nMinahonda\nCosto:\n11375"}
MultiLanguageSpellData['mx'][466019] = {name = "Trituradora de Aguasnegras Deluxe Mk 2", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Es mejor que no preguntes qué pasó con el modelo Mk 1.\"\nVendedora:\nSubalterna HardeeZona:\nMinahondaCosto:\n8125"}
MultiLanguageSpellData['mx'][466020] = {name = "C.H.A.T.A.R.R.A.dora goblin personalizada", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Las trituradoras goblin han demostrado una y otra vez que tienen muchas aplicaciones, como el paisajismo y el transporte. Este modelo ha sido adaptado para las necesidades de C.H.A.T.A.R.R.A.\"\nBotín:\nPila de basura tamizada\nZona:\nMinahonda"}
MultiLanguageSpellData['mx'][466021] = {name = "Trituradora goblin violeta", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Esta trituradora está pintada meticulosamente con una pintura anticorrosión para que su brillo resista el paso del tiempo.\"\nBotín:\nEnvíos y Manipulación\nZona:\nMinahonda"}
MultiLanguageSpellData['mx'][466022] = {name = "Coordinaventuras", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Diseñada para gestionar cualquier operación de Ventura desde el frente de batalla.\"\nBotín:\nTesoro de Ventura y Cía.\nZona:\nMinahonda"}
MultiLanguageSpellData['mx'][466023] = {name = "Defensor de dispositivos", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Asegura a los demás que tus activos están exactamente donde deben estar.\"\nVendedor:\nSkedgit CeniestallidosZona:\nMinahondaCosto:\n25"}
MultiLanguageSpellData['mx'][466024] = {name = "Protobombardero Pantoque", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Para el transporte rápido de objetos comerciables del cártel y otras sustancias altamente volátiles.\"\nBotín:\nTesoro de Pantoque\nZona:\nMinahonda"}
MultiLanguageSpellData['mx'][466025] = {name = "Manipulador de márgenes", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Asegura que siempre haya una distancia marginal entre el piso y tú.\"\nVendedor:\nSkedgit Ceniestallidos\nZona:\nMinahonda\nCosto:\n25"}
MultiLanguageSpellData['mx'][466026] = {name = "Máquina voladora goblin recuperada de archimegamillonario", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Si bien antes era una posesión preciada entre la élite de la sociedad goblin, está máquina voladora fue tristemente relegada a la montaña de basura cuando un modelo más grande, brillante y explosivo llegó al mercado.\"\nBotín:\nBasura del Gallagio\nZona:\nMinahonda"}
MultiLanguageSpellData['mx'][466027] = {name = "Ojoespía mechaoscura", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Ideal para todo aquel que quiera escalar posiciones entrometiéndose en los asuntos de TODO EL MUNDO.\"\nMisión de mundo:\nPrecipitado mechaoscura\nZona:\nMinahonda"}
MultiLanguageSpellData['mx'][466028] = {name = "Máquina voladora verde mezquino", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Los mejores ingenieros de Bonvapor aseguran que esta genialidad de la mecánica fue obra suya, mientras que los demás cárteles solo copiaron sus planos.\"\nVendedora:\nAsistente de laboratorio Laszly\nZona:\nMinahonda\nCosto:\n11375"}
