MultiLanguageSpellData['mx'][467024] = {name = "Transportador de Kaja'Cola", additional_info = "[q]Las curiosidades extraviadas ahora tienen un 35% de probabilidad de contener 1 Kaja'Colas y ahora, una vez por abismo, Brann invoca un paquete de 6 Kaja' cuando enciende hogueras.\n\n Hay distintos sabores de Kaja'Cola, cada uno con un efecto particular que se aplica cuando se recolecta."}
MultiLanguageSpellData['mx'][467026] = {name = "Granada saltarina goblomagnética", additional_info = "[q]Brann tiene una probabilidad de lanzar en combate una granada SGM a un objetivo enemigo, lo que inflige daño de naturaleza moderado y tiene un 20% de probabilidad de aturdir durante 1.5 s. Esto tiene un 25% de probabilidad de rebotar contra otro objetivo.\n\n La granada puede rebotar en miembros del grupo sin peligro."}
MultiLanguageSpellData['mx'][467029] = {name = "Matriz de conversión de impacto", additional_info = "[q]Cuando entra en combate, Brann activa la matriz de conversión durante 10 s. Un porcentaje pequeño de todo el daño que inflige el grupo durante este tiempo se convierte en estadística principal y se divide entre los miembros del grupo.\n\n Cuando se apaga la matriz de conversión, la bonificación de estadística principal persiste 10 s. Este efecto no puede ocurrir más de una vez cada 2 min."}
MultiLanguageSpellData['mx'][467031] = {name = "Flujo de sangre negra", additional_info = "Rango ilimitado\nInstante\n[q]Cae sangre negra del techo de la fábrica, que inflige 14 p. de daño de las sombras cada 0.5 s."}
MultiLanguageSpellData['mx'][467032] = {name = "Fuego de huevo", additional_info = nil}
MultiLanguageSpellData['mx'][467033] = {name = "C4Z4B0T1N3S", additional_info = "[q]Cada 60 s o tras 5 s de haber entrado en combate, escanea el entorno, marca las curiosidades extraviadas y hace que los enemigos con menos del 95% de salud reciban un 4% más de daño durante 10 s."}
MultiLanguageSpellData['mx'][467034] = {name = "Bomba letal goblin de ingeniería inversa", additional_info = "[q]Cuando la salud de un jugador cae por debajo del 50% en combate, Brann lanza una bomba gigante que explota al impactar.\n\n La explosión repele y ralentiza un 45% a los enemigos cercanos durante 5 s, y restaura a los miembros del grupo cercanos un 35% de su salud máxima. Solo puede ocurrir una vez cada 1.5 min."}
MultiLanguageSpellData['mx'][467035] = {name = "Imán cómicamente grande", additional_info = "[q]Cuando Brann usa Herramientas de recolección , hay una probabilidad del 100% de magnetizar placas descartadas sobre los miembros del grupo, lo que les otorga un escudo equivalente al 5% de su salud máxima que se regenera cuando está fuera de combate.\n\n Herramientas de recolección\nBrann utiliza sus herramientas de recolección para ayudar a los jugadores a encontrar más oro, menas, hierbas, pescado, cueros y tesoros."}
MultiLanguageSpellData['mx'][467036] = {name = "Propulsor a biocombustible", additional_info = "[q]Los miembros del grupo se equipan con un Equipamiento de cohete a biocombustible .\n\n Biocombustible\n Cada enemigo derrotado alimenta el Equipamiento de cohete a biocombustible , lo que aumenta la velocidad de movimiento un 2% y la celeridad un 2% durante 10 s. Se acumula hasta 10 veces."}
MultiLanguageSpellData['mx'][467037] = {name = "Chip de mejora marcado", additional_info = "[q]La salud máxima de Brann aumenta un 4% y el daño y la sanación que realiza aumentan un 20%.\n\n Cuando está en combate, Brann puede convertirse en el objetivo de robots mecánicos que se ensañan con él, pero que pueden ser destruidos o disipados. Si llegan a Brann, recibirá un daño equivalente al 30% de su salud máxima y quedará aturdido durante 5 s."}
