MultiLanguageSpellData['mx'][471365] = {name = "Minahonda", additional_info = "Instante\n[q]Habilidad recomendada: 375\n\n Fluyen canales de escorrentía de Bonvapor de las distintas tuberías. Sus aguas solo están habitadas por los peces fuertes de Khaz Algar y cualquier otra cosa que pueda tolerar ese líquido intenso.\n\n Estanques que se encuentran en esta zona:\n - Brillacuática\n - Derrame de icor infundido\n - Escorrentía de Bonvapor\nProfesión:\nPesca (225)"}
MultiLanguageSpellData['mx'][471366] = {name = "Cuerda de tracción", additional_info = "[q0]Talento\n[q]Mientras Disparo certero está activo, consumir Disparos precisos extiende 1.0 s la duración de Disparo certero, hasta 5.0 s.\n\n Además, Disparo certero ahora aumenta un 50% la efectividad de Aerodinamización."}
MultiLanguageSpellData['mx'][471368] = {name = "Intercambio de peces \"dorados\" de Rebeca", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]Rebeca Róbalo y su equipo de pescadores, que se encuentran en el canal central del Suburbio Quimistral, han mostrado especial interés en los peces \"dorados\" locales de Minahonda.\n\n ¡Pasa para colaborar con el esfuerzo de preservación y obtén recompensas!\nProfesión:\nPesca (225)"}
