MultiLanguageSpellData['mx'][1215707] = {name = "Paladin Retribution 11.1 Class Set 2pc", additional_info = "Aproximadamente 10 activaciones por minuto\n[q]Tus hechizos y habilidades tienen una probabilidad de activar ¡Racha de victorias! , lo que aumenta el daño de tus Veredicto del templario y Tormenta divina un 2%. Se acumula hasta 10 veces. Gastar poder sagrado en habilidades que infligen daño tiene una probabilidad del 12% de eliminar ¡Racha de victorias!"}
MultiLanguageSpellData['mx'][1215709] = {name = "Paladin Retribution 11.1 Class Set 4pc", additional_info = "[q]Cuando pierdes tu ¡Racha de victorias! , recuperas lo último de poder sagrado que gastaste, no podrás perder poder sagrado durante los próximos 4.0 s, y el daño de tus habilidades de poder sagrado aumentará un 10%."}
MultiLanguageSpellData['mx'][1215710] = {name = "Shaman Enhancement 11.1 Class Set 2pc", additional_info = "Aproximadamente 10 activaciones por minuto\n[q]Tus hechizos y habilidades tienen una probabilidad de activar ¡Racha de victorias! , lo que aumenta un 5% el daño de tu Golpe de tormenta, Latigazo de lava y Vientos de perdición hasta un máximo del 25%. Las habilidades que gastan Arma vorágine tienen un 1.0% de probabilidad de eliminar ¡Racha de victorias! por cada Arma vorágine gastada."}
