MultiLanguageSpellData['mx'][1215712] = {name = "Shaman Enhancement 11.1 Class Set 4pc", additional_info = "[q]Cuando pierdes tu ¡Racha de victorias! , los vientos cambian a Vientos de perdición durante 3 s. Cuando Vientos de perdición inflige daño, tu siguiente Relámpago estruendoso inflige un 12.0% más de daño, hasta un 60.0%. Puedes guardar hasta 10 acumulaciones. Además, Relámpago estruendoso inflige un 75% más de daño a tu objetivo principal.\n(100ms de reutilización)"}
MultiLanguageSpellData['mx'][1215713] = {name = "Warrior Arms 11.1 Class Set 2pc", additional_info = "Aproximadamente 10 activaciones por minuto\n[q]Tus habilidades tienen una probabilidad de activar ¡Racha de victorias! , lo que aumenta un 5% el daño de tu Abrumar. Se acumula hasta 10 veces.\n Abrumar tiene un 15% de probabilidad de eliminar ¡Racha de victorias!"}
MultiLanguageSpellData['mx'][1215714] = {name = "Warrior Fury 11.1 Class Set 2pc", additional_info = "Aproximadamente 10 activaciones por minuto\n[q]Tus habilidades tienen una probabilidad de activar ¡Racha de victorias! , lo que aumenta un 2% el daño de Desenfreno. Se acumula hasta 10 veces.\n Desenfreno tiene un 15% de probabilidad de eliminar ¡Racha de victorias!"}
MultiLanguageSpellData['mx'][1215715] = {name = "Warrior Fury 11.1 Class Set 4pc", additional_info = "[q]Cuando obtienes una acumulación de ¡Racha de victorias! , tienes la misma probabilidad de que tu siguiente Sed de sangre inflija un 15% más de daño y que aumente un 25% tu probabilidad de golpe crítico, o que tu siguiente Arremetida enfurecida inflija un 15% más de daño y genere 2 p. más de ira."}
