MultiLanguageSpellData['mx'][1215717] = {name = "Monk Windwalker 11.1 Class Set 2pc", additional_info = "Aproximadamente 10 activaciones por minuto\n[q]Tus hechizos y habilidades tienen una probabilidad de activar ¡Racha de victorias! , lo que aumenta un 3% el daño de tu Patada del sol naciente y Patada giratoria de la grulla. Se acumula hasta 10 veces. Patada del sol naciente y Patada giratoria de la grulla tienen un 15% de probabilidad de eliminar ¡Racha de victorias!"}
