MultiLanguageSpellData['mx'][1218316] = {name = "Corrupción de los Aspectos", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a Corrupción de los Aspectos. Esta montura cambia según tu habilidad en equitación y tu ubicación.\n[q]\"Con el triunfo de N'Zoth, los primeros pasos que dio Galakrond empiezan a dar frutos. Sin los Aspectos, la corrupción de su especie ha culminado.\"\nVendedora:\nTori\nZona:\nDornogal\nCosto:\n40000"}
MultiLanguageSpellData['mx'][1218317] = {name = "Pantera de cristal del Vacío", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a una Pantera de cristal del Vacío que se puede montar.\n[q]\"Si bien muchas gemas preciosas han sido corrompidas por energías del Vacío en las visiones horribles, los maestros joyeros aún pueden usarlas para crear poderosas monturas de panteras.\"\nProfesión:\nJoyería"}
