MultiLanguageSpellData['mx'][1226487] = {name = "Enfoque del gran bastón", additional_info = "Rango ilimitado\nInstante\n[q]Provoca la ira del arma de Diurna y consume una carga de Cólera del gran bastón. El arma emite un haz concentrado de energía de tormenta hacia el suelo que persigue al jugador e inflige 20 p. de daño de naturaleza a los jugadores en un radio de 3 m cada medio segundo durante la persecución."}
MultiLanguageSpellData['mx'][1226488] = {name = "Gigabomba descargada", additional_info = "Rango ilimitado\nInstante\n[q]Inflige 922360 p. de daño de naturaleza cada 3 s a los 5 jugadores más cercanos.\n\n Cuando interactúas, se convierte en Gigabomba descargada e inflige 922360 p. de daño de naturaleza cada 1.5 s. Este efecto se acumula."}
MultiLanguageSpellData['mx'][1226489] = {name = "Cohetes sobrecargados", additional_info = "Rango ilimitado\nInstante\n[q]Una explosión inmensa fija unos cohetes sobrecargados en los necios desprevenidos durante 6 s .\n\n Al quitarlos, los cohetes se disparan en direcciones indicadas e infligen 2934780 p. de daño de fuego por segundo durante 9 s a los jugadores impactados, lo que los repele."}
MultiLanguageSpellData['mx'][1226492] = {name = "Ritual interrumpido", additional_info = "Alcance de 50 m\nInstante\n[q]La interrupción del ritual hace que el taumaturgo quede aturdido y reciba un 30% más de daño durante 6 s."}
MultiLanguageSpellData['mx'][1226493] = {name = "Alma destrozada", additional_info = "Rango ilimitado\nInstante\n[q]Ilyssa destroza el alma del objetivo, lo que aumenta el daño que recibe de Fractura un 125% durante 36 s."}
