MultiLanguageSpellData['mx'][1226511] = {name = "Segaerizo primaveral", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a esta montura.\n[q]\"El Segaerizo primaveral exhibe toda su energía por la mañana. Pasa la mayor parte del día buscando comida o llamando a otros segaerizos.\"\nPuesto de venta"}
