MultiLanguageSpellData['mx'][1233515] = {name = "Dispositivo de Información Segura, Contenida y Organizada", additional_info = "[q]Tus hechizos y habilidades tienen una probabilidad de convertirte en un Pararrayos que ataca a un objetivo enemigo aleatorio que esté en un radio de 40 m e inflige ( 1 * 167 ) p. de daño de naturaleza cada 3 s durante 15 s."}
MultiLanguageSpellData['mx'][1233518] = {name = "K'arroc lavanda", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"El antiguo dueño de este k'arroc particularmente agresivo murió mientras investigaba el Espacio Desatado. Quizá te acepte en su lugar... o no.\"\nVendedora:\nShad'anis\nZona:\nK'aresh\nCosto:\n10"}
