MultiLanguageSpellData['mx'][1233539] = {name = "Devorar", additional_info = "Hechizo de 2 seg\n[q]Al alcanzar 100 p. de energía, Dimensius aumenta su Densidad, lo que crea una poderosa fuerza atrayente que inflige 1686460 p. de daño de las sombras cada 1 durante 5 s y atrae a los jugadores, estrellas del Vacío, agujeros negros y el disco de crecimiento.\n\n Después de 5 s, todo jugador que esté fuera del Pozo de gravedad de una estrella del Vacío es atraído inmediatamente hacia Dimensius y cae al Olvido ."}
MultiLanguageSpellData['mx'][1233542] = {name = "El Hielahuesos", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Este trepador, un digno rival del Derritehuesos, fue expulsado de su madriguera, cerca de la Forja de Maná Omega, luego de sufrir una derrota aplastante. Ahora busca aprender del que destronó a su mayor enemigo.\"\nVándalos de Forja de Maná\nReconocimiento:\n14\nUbicación:\nPunto Sombrío"}
MultiLanguageSpellData['mx'][1233544] = {name = "Invocar alfombra de historias", additional_info = nil}
MultiLanguageSpellData['mx'][1233546] = {name = "Trepador del Vacío rubí", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Este trepador del Vacío fue \"rescatado\" por la Fundación de K'aresh para estudiarlo, y resultó ser una montura increíblemente robusta.\"\nVendedor:\nOm'sirik\nZona:\nK'aresh\nCosto:\n8125"}
MultiLanguageSpellData['mx'][1233547] = {name = "Trepador del Vacío acídico", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Este trepador se ha dado un festín de gases tóxicos, lo que hace que su cuerpo esté impregnado de poderosos ácidos.\"\nVendedora:\nShad'anis\nZona:\nK'aresh\nCosto:\n7"}
