MultiLanguageSpellData['mx'][1233553] = {name = "Prisma abisal implacable", additional_info = "[q]Tus habilidades que infligen daño atraen rayos concentrados del Vacío en el prisma, que infligen ( 441 * 1 ) p. de daño cósmico que se dividen equitativamente entre tu objetivo y los enemigos cercanos. El daño aumenta un 30% por cada enemigo golpeado, hasta un máximo del 150%. Este efecto puede ocurrir cada 10 s y acumula Poder latente en el prisma, hasta un máximo de 18 veces.\n(10s de reutilización)"}
MultiLanguageSpellData['mx'][1233556] = {name = "Prisma abisal implacable", additional_info = "{Instante} {20 seg de reutilización}\n[q]Consume todo el Poder latente para obtener 18 p. de fuerza o agilidad por acumulación durante 20 s."}
