MultiLanguageSpellData['mx'][1236145] = {name = "Púas de llamas", additional_info = "Instante\n[q]Fuego, Escarcha\nLos hechizos excepcionales lanzados por tu fénix aumentan 0.3 s la duración de tu siguiente Hipertermia. Cuando tu fénix expira, te potencia más allá de tus límites, lo que te otorga Distorsión temporal inferior y aumenta un 10% el daño con hechizos durante 10 s.\n\nArcano\nLos hechizos excepcionales lanzados por tu fénix aumentan 0.5 s la duración de tu siguiente Alma arcana. Cuando tu fénix expira, te potencia más allá de tus límites, lo que te otorga Distorsión temporal inferior y aumenta un 20% el daño con hechizos durante 10 s."}
MultiLanguageSpellData['mx'][1236146] = {name = "Carga estática", additional_info = "[q]Frenesí titánico tiene una probabilidad de activar una Carga estática."}
MultiLanguageSpellData['mx'][1236148] = {name = "Corriente eléctrica", additional_info = "[q]Frenesí titánico tiene una probabilidad de pausar tu Corriente eléctrica en su nivel actual durante hasta que se cancela."}
MultiLanguageSpellData['mx'][1236160] = {name = "Ignición", additional_info = "Rango ilimitado\nInstante\n[q]Tu objetivo arde durante 9 s y recibe un 4.0% más de daño del daño total directo causado por tu Bola de fuego, Explosión de fuego, Agostar, Piroexplosión [ Meteorito : Meteorito ] [ Llamas del Fénix : Llamas del fénix ] [ Tormenta de cenizas : Tormenta de cenizas ] y Fogonazo. Si este efecto se vuelve a aplicar, cualquier daño restante se añadirá a la nueva Ignición.\n\n Explosión de fuego provoca que tus Igniciones se propaguen a 3 enemigos cercanos."}
MultiLanguageSpellData['mx'][1236161] = {name = "Toque cargado", additional_info = "[q]Las chispas creadas al sanar a Brann infligen daño equivalente a la cantidad sanada a un objetivo enemigo en un radio de 40 m."}
MultiLanguageSpellData['mx'][1236169] = {name = "Cristal cargado", additional_info = "[q]cuando destruyes un cristal de tormenta titánico, lanzas inmediatamente un Rayo cargado sobre un enemigo en un radio de 40 m."}
