MultiLanguageSpellData['mx'][1236192] = {name = "Runa de fuerza explosiva", additional_info = "Instante\n[q]Inflige daño arcano a todas las criaturas cercanas."}
MultiLanguageSpellData['mx'][1236193] = {name = "Succionar poder", additional_info = "Alcance de 20 m\nCanalizado (Hechizo de 5 seg)\n[q]El taumaturgo succiona poder de un cristal cercano y lanza periódicamente una Emisión succionante contra los jugadores en un radio de 60 m.\n\n Después de la canalización, el daño que inflige el taumaturgo aumenta un 50%."}
