MultiLanguageSpellData['mx'][1236207] = {name = "Aluvión astral", additional_info = "Rango ilimitado\nInstante\n[q]El recolector arcano emerge con energía cuando entra en contacto con una manifestación arcana, lo que inflige 22623435 p. de daño arcano a todos los jugadores y 8432299 p. más de daño arcano cada 2 s durante 16 s."}
MultiLanguageSpellData['mx'][1236209] = {name = "Pica glacial", additional_info = "{1% del maná base} {Alcance de 40 m}\nHechizo de 2.75 seg\n[q]Conjura una pica de hielo enorme que se funde con tus Carámbanos actuales. La pica empala a tu objetivo, inflige ([654% of Spell Power]) p. de daño además de todo el daño almacenado en tus Carámbanos y congela al objetivo durante 4 s. El daño puede interrumpir el efecto de congelado.\n\n Se necesitan 5 Carámbanos para lanzarla.\n\nPasivo: Lanza de hielo ya no arroja Carámbanos."}
MultiLanguageSpellData['mx'][1236211] = {name = "Pica glacial", additional_info = "Alcance de 100 m\nInstante\n[q]Conjura una pica de hielo enorme que se funde con tus Carámbanos actuales. La pica empala a tu objetivo, inflige ([654% of Spell Power]) p. de daño además de todo el daño almacenado en tus Carámbanos y congela al objetivo durante 4 s. El daño puede interrumpir el efecto de congelado.\n\n Se necesitan 5 Carámbanos para lanzarla.\n\nPasivo: Lanza de hielo ya no arroja Carámbanos."}
MultiLanguageSpellData['mx'][1236212] = {name = "Piroexplosión", additional_info = "{1.5% del maná base} {Alcance de 40 m}\nHechizo de 4 seg\n[q]Lanza una inmensa roca en llamas que inflige ([352.5% of Spell Power]) p. de daño de fuego ."}
