MultiLanguageSpellData['mx'][1236253] = {name = "Death Knight Deathbringer 11.2 Class Set 2pc", additional_info = "[q]Escarcha, Profano\n Lanzar Marca de la parca otorga 1 acumulación de Exterminar con un 150% de efectividad para la primera guadaña y un 125% para la segunda guadaña.\n\nSangre\n Lanzar Marca de la parca otorga 2 acumulaciones de Exterminar con un 150% de efectividad para la primera guadaña y un 125% para la segunda guadaña."}
MultiLanguageSpellData['mx'][1236254] = {name = "Death Knight Deathbringer 11.2 Class Set 4pc", additional_info = "[q]Sangre, Escarcha, Profano\n Exterminar inflige un 20% más de daño, y Marca de la parca se puede acumular hasta 15 veces más. Cuando explota, Marca de la parca aumenta tu probabilidad de golpe crítico un 10% durante 8 s.\n(1s de reutilización)"}
MultiLanguageSpellData['mx'][1236256] = {name = "Hendidura vorpal", additional_info = "Alcance de 10 m\nHechizo de 2.5 seg\n[q]El taumatugo hiende el área que tiene frente a él, lo que inflige daño de las sombras y aplica un escudo de absorción de sanación a todos los jugadores que golpea."}
MultiLanguageSpellData['mx'][1236259] = {name = "Death Knight San'layn 11.2 Class Set 2pc", additional_info = "[q]Profano\n Imposición de pena extiende la duración de tu enfermedad 3.0 s más sobre tu objetivo principal, y Esencia de la Reina de Sangre también aumenta un 0.5% tu maestría por cada acumulación.\n\nSangre, Escarcha\n Imposición de pena extiende la duración de tu enfermedad 4.0 s más sobre tu objetivo principal, y Esencia de la Reina de Sangre también aumenta un 0.5% tu maestría por cada acumulación."}
MultiLanguageSpellData['mx'][1236260] = {name = "Death Knight San'layn 11.2 Class Set 4pc", additional_info = "[q]Profano\n Imposición de pena inflige un 30% más de daño y Golpe vampírico aumenta el daño de tu necrófago un 20% durante 8 s. Se pueden superponer varias aplicaciones.\n\nSangre, Escarcha\n Imposición de pena inflige un 50% más de daño y Golpe vampírico aumenta el daño de tus Armas de runas danzantes un 20% durante 8 s. Se pueden superponer varias aplicaciones."}
MultiLanguageSpellData['mx'][1236262] = {name = "Dragón sabio de Shaohao", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a esta montura.\n[q]\"Las lecciones que Shaohao aprendió en la vida y en la muerte, y la pasión que sentía por su hogar se han fusionado en este dragón etéreo, un reflejo de la sabiduría del Emperador.\"\nPromoción:\nMists of Pandaria Classic"}
MultiLanguageSpellData['mx'][1236263] = {name = "Golpe arcano", additional_info = "Alcance de 30 m\nHechizo de 1.75 seg\n[q]Inflicts 5 Arcane damage to an enemy."}
MultiLanguageSpellData['mx'][1236272] = {name = "Cadena crítica", additional_info = "Instante\nAproximadamente 1.5 activaciones por minuto\n[q]Tus hechizos y habilidades tienen una probabilidad de activar una Sobrecarga crítica que aumenta 31 p. tu golpe crítico cada 2 s durante 20 s.\n(20s de reutilización)"}
MultiLanguageSpellData['mx'][1236273] = {name = "Chispa aceleradora", additional_info = "Instante\nAproximadamente 1.5 activaciones por minuto\n[q]Tus hechizos y habilidades tienen una probabilidad de activar una Chispa aceleradora que te otorga 139 p. de celeridad durante 20 s."}
MultiLanguageSpellData['mx'][1236275] = {name = "Carga estática", additional_info = "Instante\nAproximadamente 1.5 activaciones por minuto\n[q]Tus hechizos y habilidades tienen una probabilidad de otorgarte una Carga estática que aumenta ( 14 * 20) p. tu versatilidad durante 30 s. Cada uno de tus próximos hechizos y habilidades reduce un 5% la bonificación de versatilidad.\n(29s de reutilización)"}
MultiLanguageSpellData['mx'][1236276] = {name = "Corriente eléctrica", additional_info = "Instante\n[q]Obtienes una Corriente eléctrica al entrar en combate que aumenta 8 p. tu maestría cada 2 s hasta un máximo de (12 * 8 ) tras 24 s, y luego se restablece y se repite."}
MultiLanguageSpellData['mx'][1236277] = {name = "Toque cargado", additional_info = "Instante\nAproximadamente 2 activaciones por minuto\n[q]Tus sanaciones tienen una probabilidad de crear chispas que saltan al objetivo que tenga la salud más baja en un radio de 40 m para restablecerle 1766 p. de salud."}
MultiLanguageSpellData['mx'][1236278] = {name = "Escudo de energía", additional_info = "Instante\nAproximadamente 1.5 activaciones por minuto\n[q]Cuando recibes daño, tienes una probabilidad de obtener un escudo de energía titánico que absorbe hasta 3662 p. de daño durante 10 s. Cuando el escudo expira, inflige daño arcano equivalente a un 30% de la absorción restante dividido entre los enemigos que están en un radio de 8 m."}
MultiLanguageSpellData['mx'][1236279] = {name = "Cristal cargado", additional_info = "Instante\nAproximadamente 1.5 activaciones por minuto\n[q]Tus hechizos y ataques tienen una probabilidad de lanzar una Descarga cargada contra tu objetivo que inflige 965 p. de daño de naturaleza divididos entre los objetivos que están en un radio de 8 m."}
