MultiLanguageSpellData['mx'][1236330] = {name = "Druid Druid of the Claw 11.2 Class Set 4pc", additional_info = "[q]Feral\n Devastar tiene un 40% de probabilidad de volver a Devastar a tu objetivo 4 s después con un 100% del poder inicial.\n\nEquilibrio, Guardián, Restauración\n Devastar tiene un 40% de probabilidad de volver a Devastar a tu objetivo 4 s después con un 60% de efectividad."}
MultiLanguageSpellData['mx'][1236331] = {name = "Druid Druid of the Claw 11.2 Class Set 2pc", additional_info = "[q]Devastar aumenta un 10% tu celeridad, un 10% tu probabilidad de asestar un golpe crítico y un 30% el daño que infligen tus efectos de sangrado durante 5 s.\n(100ms de reutilización)"}
MultiLanguageSpellData['mx'][1236332] = {name = "Druid Elune's Chosen 11.2 Class Set 2pc", additional_info = "[q]Equilibrio\n El daño de Fuego estelar aumenta un 15%. Obtener Poder astral con Fuego estelar tiene un 40% de probabilidad de lanzar una Oleada de estrellas contra una víctima con un 45% de efectividad.\n\nFeral, Guardián, Restauración\n El daño de Vapulear aumenta un 20%. Vapulear tiene un 40% de probabilidad de lanzar una Oleada de estrellas contra una víctima con un 160% de efectividad.\n\n(100ms de reutilización)"}
MultiLanguageSpellData['mx'][1236333] = {name = "Druid Elune's Chosen 11.2 Class Set 4pc", additional_info = "[q]Equilibrio\n Al hacer impacto, las Oleadas de estrellas que lanza Fuego estelar se dividen y golpean a un máximo de 3 objetivos más con un 40% de efectividad y otorgan una acumulación de Luz de luna creciente. Lanzar Furia de Elune o Luna llena consume Luz de luna creciente para aumentar un 4% tu daño por cada acumulación durante 12 s.\n\nFeral, Guardián, Restauración\n Al hacer impacto, las Oleadas de estrellas que lanza Vapulear se dividen y golpean a un máximo de 3 objetivos más con un 20% de efectividad y otorgan una acumulación de Luz de luna creciente. Lanzar Haz lunar consume Luz de luna creciente para aumentar un 4% tu daño por cada acumulación durante 12 s."}
MultiLanguageSpellData['mx'][1236334] = {name = "Druid Keeper of the Grove 11.2 Class Set 2pc", additional_info = "[q]Equilibrio, Feral, Guardián\n Lanzar Alineación celestial invoca la ayuda de una dríade durante 10 s que lanza Oleada de estrellas con un 360% de efectividad y Lluvia de estrellas con un 800% de efectividad.\n\nRestauración\n Lanzar Encarnación: Árbol de la vida o Convocar los espíritus invoca la ayuda de una dríade durante 5 s que lanza Tranquilidad con un 50% de efectividad y usa instantáneamente Recrecimiento con tu aliado que tenga menos salud con un 200% de efectividad."}
MultiLanguageSpellData['mx'][1236336] = {name = "Druid Keeper of the Grove 11.2 Class Set 4pc", additional_info = "[q]Restauración\n Cuando tu Dríade se disipa, tus siguientes 2 lanzamientos de Alivio presto sanan una cantidad equivalente al 5% de la sanación realizada mientras estaba activa y propaga un 25% de su sanación a los aliados cercanos. Este efecto se reduce cuando alcanza a más de 5 objetivos.\n\nEquilibrio, Feral, Guardián\n Cuando tu Dríade se disipa, tus siguientes 2 lanzamientos de Oleada de estrellas infligen una cantidad de daño equivalente al 3% del daño infligido mientras estaba activa y propaga un 10% de su daño a los enemigos cercanos. Este efecto se reduce cuando alcanza a más de 5 objetivos."}
MultiLanguageSpellData['mx'][1236337] = {name = "Druid Wildstalker 11.2 Class Set 2pc", additional_info = "[q]Equilibrio, Guardián, Restauración\n La velocidad de crecimiento de Floraciones simbióticas aumenta un 45%. Lanzar Recrecimiento con Lanzamiento libre hace que Floraciones simbióticas crezca sobre un máximo de 2 aliados cercanos válidos.\n\nFeral\n La velocidad de crecimiento de Vides buscasangre aumenta un 40%. Furia del tigre hace que Vides buscasangre crezca sobre un máximo de 3 enemigos cercanos válidos."}
MultiLanguageSpellData['mx'][1236338] = {name = "Druid Wildstalker 11.2 Class Set 4pc", additional_info = "[q]Equilibrio, Guardián, Restauración\n Floraciones simbióticas tiene una probabilidad del 35% de activar Crecimiento explosivo cada 2 s con un 100% de efectividad. Cada acumulación de Floraciones simbióticas que tenga un aliado aumenta la sanación recibida un 30%.\n\nFeral\n Vides buscasangre tiene una probabilidad del 20% de activar Crecimiento explosivo cada 2 s con un 100% de efectividad. Cada acumulación de Vides buscasangre que tenga un enemigo aumenta el daño recibido un 40%."}
MultiLanguageSpellData['mx'][1236342] = {name = "Preparándose para atacar", additional_info = "Instante\n[q]Feral\nDevastar tiene un 40% de probabilidad de volver a Devastar a tu objetivo 4 s después con un 100% del poder inicial.\n\nEquilibrio, Guardián, Restauración\nDevastar tiene un 40% de probabilidad de volver a Devastar a tu objetivo 4 s después con un 60% de efectividad."}
