MultiLanguageSpellData['mx'][1236348] = {name = "Tajo cargado", additional_info = "Alcance de 100 mHechizo de 4 seg 3 seg de reutilización\n[q]Zo'phex carga sus espadas para desatar un corte enorme que inflige 15758921 p. de daño físico a todos los enemigos frente a él."}
MultiLanguageSpellData['mx'][1236350] = {name = "Void Power Shard Released Visuals - COSMETIC", additional_info = nil}
MultiLanguageSpellData['mx'][1236354] = {name = "Succión de alma", additional_info = "Alcance de 40 mHechizo de 2 seg 5 seg de reutilización\n[q]Ralentiza al objetivo y drena 622547 p. de salud durante 8 s, lo que sana al taumaturgo el doble de la cantidad drenada."}
MultiLanguageSpellData['mx'][1236355] = {name = "Death Knight Rider of the Apocalypse 11.2 Class Set 2pc", additional_info = "[q]Sangre, Profano\n Apocalipsis inmediato ahora invoca a Melenablanca durante 10 s. La No-muerte de Melenablanca inflige un 20% más de daño, infecta a 1 objetivo más cuando se propaga y su Espiral de la muerte inflige un 35% más de daño.\n\nEscarcha\n Pilar de escarcha ahora invoca a Aterratrols durante 10 s. Furia helada de Aterratrols inflige un 20% más de daño, y el lanzamiento de Asolar de Aterratrols inflige un 15% más de daño."}
MultiLanguageSpellData['mx'][1236356] = {name = "Death Knight Rider of the Apocalypse 11.2 Class Set 4pc", additional_info = "[q]Escarcha\n Lanzar Asolar o Guadaña de escarcha hace que Aterratrols lance su Asolar o Guadaña de escarcha contigo con un 100% de efectividad. Tu Asolar inflige un 20% de daño más a los objetivos afectados por la Furia helada de Aterratrols.\n\nSangre, Profano\n Lanzar Espiral de la muerte o Epidemia hace que Melenablanca lance su Espiral de la muerte o Epidemia contigo con un 125% de efectividad. Tu Espiral de la muerte inflige un 40% más de daño a los objetivos afectados por la No-muerte de Melenablanca.\n\n(500ms de reutilización)"}
MultiLanguageSpellData['mx'][1236358] = {name = "Demon Hunter Aldrachi Reaver 11.2 Class Set 2pc", additional_info = "[q]El daño de Guja de atracador aumenta un 50% y el resto del daño físico aumenta un 25%."}
MultiLanguageSpellData['mx'][1236360] = {name = "Demon Hunter Aldrachi Reaver 11.2 Class Set 4pc", additional_info = "[q]Caos\n Furia de los aldrachi potencia aún más a Danza de hojas cuando se lanza después de Golpe de caos, lo que aumenta la cantidad de cortes a 12.\n\n Marca del atracador ahora se acumula hasta 2 veces y potencia aún más a Golpe de caos cuando se lanza después de Danza de hojas, lo que aplica una acumulación más equivalente al 100% de la duración normal.\n\nVenganza\n Furia de los aldrachi potencia aún más a Rajar alma cuando se lanza después de Cortar, lo que aumenta la cantidad de cortes a 12.\n\n Marca del atracador ahora se acumula hasta 2 veces y potencia aún más a Cortar cuando se lanza después de Rajar alma, lo que aplica una acumulación más equivalente al 100% de la duración normal."}
MultiLanguageSpellData['mx'][1236361] = {name = "Demon Hunter Fel-Scarred 11.2 Class Set 2pc", additional_info = "[q]Caos\n Aura de inmolación inflige un 30% más de daño y aumenta el daño de Golpe de caos un 20% mientras está activa.\n\nVenganza\n Aura de inmolación inflige un 30% más de daño y aumenta el daño de Rajar alma un 20% mientras está activa."}
MultiLanguageSpellData['mx'][1236362] = {name = "Demon Hunter Fel-Scarred 11.2 Class Set 4pc", additional_info = "[q]Caos\n Adoptar la forma de demonio inmediatamente induce una Oleada demoníaca y destroza un fragmento de alma de demonio, lo que otorga un 20% más de daño durante 10 s.\n\nVenganza\n Adoptar la forma de demonio inmediatamente induce una Oleada demoníaca y destroza un fragmento de alma de demonio, lo que otorga un 20% más de daño durante 15 s.\n\n(100ms de reutilización)"}
MultiLanguageSpellData['mx'][1236364] = {name = "Evoker Flameshaper 11.2 Class Set 2pc", additional_info = "[q]Envolver aviva tu Llama interna, lo que aumenta un 25% tus efectos de daño y sanación con el tiempo, y aumenta un 50% tu probabilidad de obtener Ráfaga esencial durante 12 s. Se acumula hasta 2 veces. Se pueden superponer varias aplicaciones."}
MultiLanguageSpellData['mx'][1236365] = {name = "Evoker Flameshaper 11.2 Class Set 4pc", additional_info = "[q]Devastación\n Cuando consumes Ráfaga esencial durante Llama interna, lanzas una Bomba de esencia contra tu objetivo, lo que inflige ([371% of Spell Power])p. de daño arcano a los enemigos cercanos. Este efecto se reduce cuando alcanza a más de 5 objetivos.\n\nPreservación, Aumento\n Cuando consumes Ráfaga esencial durante Llama interna, lanzas una Bomba de esencia contra tu objetivo, lo que restaura ([250% of Spell Power]) p. de salud a los aliados cercanos. Este efecto se reduce cuando alcanza a más de 5 objetivos."}
MultiLanguageSpellData['mx'][1236366] = {name = "Evoker Scalecommander 11.2 Class Set 2pc", additional_info = "[q]Aumento\n Mientras vuelas durante Aliento profundo y durante 20 s después, diriges a un escuadrón de 2 dracthyr que atacan a tus objetivos con Desintegrar y Pira.\n\nDevastación, Preservación\n Mientras vuelas durante Aliento profundo y durante 10 s después, diriges a un escuadrón de 2 dracthyr que atacan a tus objetivos con Desintegrar y Pira."}
MultiLanguageSpellData['mx'][1236367] = {name = "Evoker Scalecommander 11.2 Class Set 4pc", additional_info = "[q]Devastación\n Mientras tu escuadrón está activo, tu Desintegración en masa golpea a un máximo de 2 objetivos más. Además, tu escuadrón te asiste durante 5 s más.\n\nAumento\n Mientras tu escuadrón está activo, tu Erupción masiva golpea a un máximo de 2 objetivos más. Además, tu escuadrón te asiste durante 10 s más.\n\nPreservación\n Mientras tu escuadrón está activo, tu Erupción masiva golpea a un máximo de 2 objetivos más. Además, tu escuadrón te asiste durante 5 s más."}
MultiLanguageSpellData['mx'][1236368] = {name = "Evoker Chronowarden 11.2 Class Set 2pc", additional_info = "[q]Reduce 60 s el tiempo de reutilización de Inclinar la balanza."}
MultiLanguageSpellData['mx'][1236369] = {name = "Evoker Chronowarden 11.2 Class Set 4pc", additional_info = "[q]Estallido temporal hace que Cronollamas golpee a 2 objetivos más y repita un 15% del daño o la sanación adicional, hasta un máximo de [(Poder con Hechizos * 4.5) * (1 + Versatilidad)], y aumenta un 30% el daño y la sanación de las habilidades de esencia."}
MultiLanguageSpellData['mx'][1236370] = {name = "Hunter Dark Ranger 11.2 Class Set 2pc", additional_info = "[q]Puntería, Supervivencia\n Aumenta un 10% el daño de Flecha negra y un 20% el daño de Pólvora lúgubre. El tiempo de reutilización de Disparo certero se reduce 30 s.\n\nBestias\n Aumenta un 10% el daño de Flecha negra y un 20% el daño de Pólvora lúgubre. El tiempo de reutilización de Llamado de la naturaleza se reduce 60 s."}
MultiLanguageSpellData['mx'][1236371] = {name = "Hunter Dark Ranger 11.2 Class Set 4pc", additional_info = "[q]Bestias, Puntería, Supervivencia\n El daño de las Flechas negras de Fuego fulminante aumenta un 50%. Consumir Arremetida mortal tiene una probabilidad del 50% de hacer que todos los aluviones de Flecha negra durante tu siguiente Fuego fulminante disparen 1 Flecha negra más."}
MultiLanguageSpellData['mx'][1236372] = {name = "Hunter Pack Leader 11.2 Class Set 2pc", additional_info = "[q]Puntería, Supervivencia\n El daño de la mascota aumenta un 15% y el daño de la bestia aumenta un 15%. Invocar una bestia otorga un 6% de celeridad, maestría o probabilidad de golpe crítico según la bestia invocada durante 8 s.\n\nBestias\n El daño de la mascota aumenta un 5% y el daño de la bestia aumenta un 15%. Invocar una bestia otorga un 6% de celeridad, maestría o probabilidad de golpe crítico según la bestia invocada durante 8 s."}
MultiLanguageSpellData['mx'][1236373] = {name = "Hunter Pack Leader 11.2 Class Set 4pc", additional_info = "[q]Invocar una bestia mientras estás bajo los efectos de Liderar la vanguardia provoca que la fauna cercana cargue contra tu objetivo con una Estampida que inflige [([300% of Attack Power]) * 9] p. de daño físico a un máximo de 8 enemigos durante 7 s."}
MultiLanguageSpellData['mx'][1236374] = {name = "Hunter Sentinel 11.2 Class Set 2pc", additional_info = "[q]Bestias, Supervivencia\n El daño de Bomba de fuego salvaje aumenta un 10%. Cuando Tormenta lunar se disipa, obtienes Don de Elune, que hace que tus siguientes 2 lanzamientos de Bomba de fuego salvaje inflijan daño arcano y que su daño inicial aumente un 150%.\n\nPuntería\n El daño de Fuego rápido aumenta un 25%. Cuando Tormenta lunar se disipa, obtienes Don de Elune, que hace que tus siguientes 2 lanzamientos de Disparo de puntería inflijan daño arcano y que su daño aumente un 10%."}
MultiLanguageSpellData['mx'][1236375] = {name = "Hunter Sentinel 11.2 Class Set 4pc", additional_info = "[q]Puntería\n El daño de Centinela aumenta un 18%. El Don de Elune ahora está activo todo lo que dure Tormenta lunar con un 100% de efectividad.\n\nBestias, Supervivencia\n El daño de Centinela aumenta un 20%. El Don de Elune ahora está activo todo lo que dure Tormenta lunar con un 100% de efectividad."}
