MultiLanguageSpellData['mx'][1236377] = {name = "Monk Master of Harmony 11.2 Class Set 2pc", additional_info = "[q]Maestro cervecero\n Obtener vitalidad aumenta la probabilidad de hacer que tu siguiente Palma del tigre desate una Oleada armónica, lo que inflige [180 * ([400% of Spell Power]) / 100] p. de daño de naturaleza divididos entre tu objetivo y otros enemigos cercanos y restaura [20 * ([500% of Spell Power]) / 100] p. de salud a un máximo de 5 aliados heridos.\n\nViajero del viento, Tejedor de niebla\n Obtener vitalidad aumenta la probabilidad de hacer que tu siguiente Palma del tigre desate una Oleada armónica, lo que inflige [20 * ([400% of Spell Power]) / 100] p. de daño de naturaleza divididos entre tu objetivo y otros enemigos cercanos y restaura [90 * ([500% of Spell Power]) / 100] p. de salud a un máximo de 5 aliados heridos."}
MultiLanguageSpellData['mx'][1236378] = {name = "Monk Master of Harmony 11.2 Class Set 4pc", additional_info = "[q]Viajero del viento, Tejedor de niebla\n Lanzar Té de enfoque del trueno garantiza que tus siguientes 2 lanzamientos de Palma del tigre activen una Oleada armónica.\n\nMaestro cervecero\n Lanzar garantiza que tus siguientes 2 lanzamientos de Palma del tigre activen una Oleada armónica."}
MultiLanguageSpellData['mx'][1236379] = {name = "Monk Shado-Pan 11.2 Class Set 2pc", additional_info = "[q]Maestro cervecero\n Golpes de aluvión inflige un 10% más de daño, y activar Armas de orden otorga al instante 10 acumulaciones de Golpes de aluvión que se activan con tu siguiente ataque con un 70% de efectividad.\n\nViajero del viento, Tejedor de niebla\n Golpes de aluvión inflige un 20% más de daño, y activar Tormenta, Tierra y Fuego otorga al instante 10 acumulaciones de Golpes de aluvión que se activan con tu siguiente ataque con un 70% de efectividad."}
MultiLanguageSpellData['mx'][1236380] = {name = "Monk Shado-Pan 11.2 Class Set 4pc", additional_info = "[q]Maestro cervecero, Tejedor de niebla\n La generación de Carga de aluvión aumenta un 50% y Golpes de aluvión se activa cada 150 p. de energía consumidos durante Armas de orden.\n\nViajero del viento\n La generación de Carga de aluvión aumenta un 50% y Golpes de aluvión se activa cada 150 p. de energía consumidos durante Tormenta, Tierra y Fuego."}
MultiLanguageSpellData['mx'][1236381] = {name = "Monk Conduit of the Celestials 11.2 Class Set 2pc", additional_info = "[q]Viajero del viento\n Corazón de la Dragona de jade también se activa durante 4 s con un 100% de efectividad después de lanzar Vientos cortantes.\n\nMaestro cervecero, Tejedor de niebla\n Corazón de la Dragona de jade también se activa durante 8 s con un 100% de efectividad después de lanzar Té de enfoque del trueno.\n\n(1s de reutilización)"}
MultiLanguageSpellData['mx'][1236382] = {name = "Monk Conduit of the Celestials 11.2 Class Set 4pc", additional_info = "[q]Corazón de la Dragona de jade aumenta un 10% tu celeridad mientras está activo y durante 4 s cuando se disipa."}
MultiLanguageSpellData['mx'][1236383] = {name = "Paladin Herald of the Sun 11.2 Class Set 2pc", additional_info = "[q]Reprensión\n La sanación y el daño de Albaluz aumentan un 30% y obtienes Cólera solar después de que Cólera vengativa se disipa, lo que hace que el efecto de Avatar del sol dure [10][10] s más.\n\nProtección\n La sanación y el daño de Albaluz aumentan un 30% y obtienes Cólera solar después de que Cólera vengativa se disipa, lo que hace que el efecto de Avatar del sol dure [10][10] s más.\n\nSagrado (Cólera vengativa)\n La sanación y el daño de Albaluz aumentan un 60% y obtienes Cólera solar después de que Cólera vengativa se disipa, lo que hace que el efecto de Avatar del sol dure 10[10][10] s más."}
MultiLanguageSpellData['mx'][1236384] = {name = "Paladin Herald of the Sun 11.2 Class Set 4pc", additional_info = "[q]Reprensión\n Cólera solar aumenta la efectividad de tus habilidades que consumen poder sagrado un 15% y te otorga [2][2] Albaluz.\n\nProtección\n Cólera solar aumenta la efectividad de tus habilidades que consumen poder sagrado un 15% y te otorga [2][2] Albaluz.\n\nSagrado (Cólera vengativa)\n Cólera solar aumenta la efectividad de tus habilidades que consumen poder sagrado un 30% y te otorga 2[2][2] Albaluz."}
