MultiLanguageSpellData['mx'][1236389] = {name = "Paladin Lightsmith 11.2 Class Set 2pc", additional_info = "[q]Protección\n El daño de Martillo y yunque aumenta un 15% y también se puede activar con con un 40% de efectividad.\n\nReprensión\n La sanación de Martillo y yunque aumenta un 15% y también se puede activar con Golpe de cruzado con un 40% de efectividad.\n\nSagrado\n La sanación de Martillo y yunque aumenta un 15% y también se puede activar con Golpe de cruzado con un 75% de efectividad.\n\n(750ms de reutilización)"}
MultiLanguageSpellData['mx'][1236390] = {name = "Paladin Lightsmith 11.2 Class Set 4pc", additional_info = "[q]Martillo y yunque también otorga una acumulación de Obra maestra, lo que hace que tu siguiente Armamento sagrado lance una versión inferior de ese mismo hechizo sobre un aliado cercano por cada acumulación."}
MultiLanguageSpellData['mx'][1236391] = {name = "Paladin Templar 11.2 Class Set 2pc", additional_info = "[q]Tu Martillo empíreo inflige un 20% de daño de golpe crítico aumentado y sus golpes críticos tienen un 50% de probabilidad de otorgar una acumulación más de Liberación de la Luz.\n(Probabilidad de que accione: 50%)"}
MultiLanguageSpellData['mx'][1236392] = {name = "Paladin Templar 11.2 Class Set 4pc", additional_info = "[q]Reprensión\n Martillo de Luz inflige un 35% más de daño a su objetivo principal, golpea a 3 objetivos secundarios más y ahora puede lanzarse 1 vez más después de Despertar de las cenizas.\n\nSagrado, Protección\n Martillo de Luz inflige un 35% más de daño a su objetivo principal, golpea a 3 objetivos secundarios más y ahora puede lanzarse 1 vez más después de Ojo de Tyr."}
MultiLanguageSpellData['mx'][1236394] = {name = "Priest Oracle 11.2 Class Set 2pc", additional_info = "[q]Sagrado, Sombra\nLanzar Rezo de alivio restaura ([1400% of Spell Power]) p. de salud a tu objetivo.\n\nDisciplina\n La primera descarga de cada Penitencia daña o sana un 200% más."}
MultiLanguageSpellData['mx'][1236395] = {name = "Priest Oracle 11.2 Class Set 4pc", additional_info = "[q]Lanzar Premonición de devoción o Premonición de consuelo otorga 2 acumulaciones de Premonición de perspicacia con un 100% de efectividad. Consumir una acumulación de Premonición de perspicacia aumenta tu celeridad un 1.0% durante 10 s. Se pueden superponer varias aplicaciones."}
MultiLanguageSpellData['mx'][1236396] = {name = "Priest Voidweaver 11.2 Class Set 2pc", additional_info = "[q]Sagrado\n El daño de Explosión del Vacío aumenta un 30%, y el tiempo de reutilización de Explosión del Vacío se reduce un 20%.\n\nSombra\n El daño de Explosión del Vacío aumenta un 30%, y el tiempo de reutilización de Explosión del Vacío se reduce un 20%. El tiempo de reutilización de Explosión del Vacío se reduce un 50%.\n\nDisciplina\n El daño de Explosión del Vacío y Penitencia aumenta un 30%, y el tiempo de reutilización de Explosión del Vacío se reduce un 20%."}
MultiLanguageSpellData['mx'][1236397] = {name = "Priest Voidweaver 11.2 Class Set 4pc", additional_info = "[q]Disciplina\n Explosión del Vacío ahora también hace que Falla entrópica crezca, mientras que Vacío colapsante aumenta el daño de Falla entrópica un 10% más, y el daño de tu siguiente Explosión mental aumenta hasta un 200% según el tamaño de la Falla entrópica cuando colapsa.\n\nSagrado, Sombra\n Explosión del Vacío ahora también hace que Falla entrópica crezca, mientras que Vacío colapsante aumenta el daño de Falla entrópica un 10% más, y el daño de tu siguiente Torrente del vacío aumenta hasta un 200% según el tamaño de la Falla entrópica cuando colapsa."}
MultiLanguageSpellData['mx'][1236398] = {name = "Priest Archon 11.2 Class Set 2pc", additional_info = "[q]Sombra\n Los halos generan 10 p. más de demencia durante 5 s, y Energía resonante también aumenta el daño de tu Peste devoradora un 5.0%.\n\nDisciplina, Sagrado\n Los halos reducen el tiempo de reutilización de tu Palabra sagrada: serenidad y Palabra sagrada: santificar 5 s, y Energía resonante también aumenta la sanación de tus Palabras sagradas un 5.0%."}
MultiLanguageSpellData['mx'][1236399] = {name = "Priest Archon 11.2 Class Set 4pc", additional_info = "[q]Sagrado\n Mientras Oleada de poder está activa, cada 2 lanzamientos de Palabra sagrada: serenidad o Palabra sagrada: santificar agrega otro halo al efecto con un 100% de efectividad, hasta un máximo de 2 veces.\n\nDisciplina, Sombra\n Mientras Oleada de poder está activa, cada 2 lanzamientos de Peste devoradora agrega otro halo al efecto con un 100% de efectividad, hasta un máximo de 2 veces."}
MultiLanguageSpellData['mx'][1236400] = {name = "Rogue Deathstalker 11.2 Class Set 2pc", additional_info = "[q]Asesinato\n Puyazo aumenta la efectividad de todos los efectos de daño y las bonificaciones de daño de Mortacechador un 60% mientras está activo.\n\nForajido, Sutileza\n Símbolos de la muerte aumenta la efectividad de todos los efectos de daño y las bonificaciones de daño de Mortacechador un 40% mientras está activo."}
MultiLanguageSpellData['mx'][1236401] = {name = "Rogue Deathstalker 11.2 Class Set 4pc", additional_info = "[q]Asesinato\n Puyazo dura 3 s más y consume una aplicación de tu Marca de mortacechador activa cuando se activa.\n\nForajido, Sutileza\n Símbolos de la muerte dura 3 s más y consume una aplicación de tu Marca de mortacechador activa cuando se activa."}
MultiLanguageSpellData['mx'][1236402] = {name = "Rogue Fatebound 11.2 Class Set 2pc", additional_info = "[q]Forajido\n Golpe fantasmal inflige un 50% más de daño y dura 4 s más.\n\n Ventaja lateral ahora provoca un lanzamiento de Moneda sinoatada adicional, y utilizar Golpe fantasmal activa su efecto.\n\nAsesinato, Sutileza\n Perdición de reyes inflige un 10% más de daño y dura 4 s más.\n\n Ventaja lateral ahora provoca un lanzamiento de Moneda sinoatada adicional, y utilizar Perdición de reyes activa su efecto."}
MultiLanguageSpellData['mx'][1236403] = {name = "Rogue Fatebound 11.2 Class Set 4pc", additional_info = "[q]Asesinato, Sutileza\n Tener una Moneda sinoatada de la suerte reduce el tiempo de reutilización de Marca mortal 30.0 s y de Perdición de reyes 15.0 s.\n\nForajido\n Tener una Moneda sinoatada de la suerte reduce el tiempo de reutilización de Subidón de adrenalina 30.0 s y de Golpe fantasmal 15.0 s."}
