MultiLanguageSpellData['mx'][1236408] = {name = "Shaman Stormbringer 11.2 Class Set 2pc", additional_info = "[q]Mejora, Restauración\n Ascensión tiene un 100% de probabilidad de otorgar una carga de Tempestad, y ahora cada 8 Tormentas despiertas se activa Ascensión durante 6.0 s.\n\nElemental\n Ascensión tiene un 100% de probabilidad de otorgar una carga de Tempestad, y ahora cada 9 Tormentas despiertas se activa Ascensión durante 6.0 s.\n\n(100ms de reutilización)"}
MultiLanguageSpellData['mx'][1236409] = {name = "Shaman Stormbringer 11.2 Class Set 4pc", additional_info = "[q]Elemental, Restauración\n El daño de naturaleza aumenta un 3.0%, y Ascensión potencia tus siguientes 2 Tempestades para formar una tormenta en lo alto que inflige ([960% of Spell Power]) p. de daño de naturaleza a su objetivo principal y reduce el daño a los enemigos cercanos después de 1.5 s.\n\nMejora\n El daño de naturaleza aumenta un 5.0%, y Ascensión potencia tus siguientes 2 Tempestades para formar una tormenta en lo alto que inflige ([400% of Attack Power]) p. de daño de naturaleza a su objetivo principal y reduce el daño a los enemigos cercanos después de 1.5 s.\n\n(100ms de reutilización)"}
MultiLanguageSpellData['mx'][1236410] = {name = "Shaman Totemic 11.2 Class Set 2pc", additional_info = "[q]Elemental, Restauración\n Después de que consumes todas las motas elementales giratorias, lanzas Diluvio con un 200% de efectividad en la ubicación de tu Tótem volátil.\n\nMejora\n Después de que consumes todas las motas elementales giratorias, tu Tótem volátil lanza Tormenta primordial con un 200% de efectividad en su ubicación."}
MultiLanguageSpellData['mx'][1236411] = {name = "Shaman Totemic 11.2 Class Set 4pc", additional_info = "[q]Elemental, Restauración\n Después de lanzar Diluvio, tus siguientes lanzamientos de Sanación en cadena, Ola de sanación u Oleada de sanación tienen un 150% de efectividad.\n\nMejora\n Después de lanzar Tormenta primordial, tus siguientes lanzamientos de Latigazo de lava o Nova de fuego tienen un 150% de efectividad.\n\n(500ms de reutilización)"}
MultiLanguageSpellData['mx'][1236413] = {name = "Warlock Hellcaller 11.2 Class Set 2pc", additional_info = "[q]Demonología, Destrucción\n Marca de Xavius aumenta el daño de Alma ennegrecida un 3% más por acumulación. Malevolencia aumenta 2 veces la cantidad de acumulaciones de Marchitar.\n\nAflicción\n Marca de Xavius aumenta el daño de Alma ennegrecida un 6% más por acumulación. Malevolencia aumenta 2 veces la cantidad de acumulaciones de Marchitar."}
MultiLanguageSpellData['mx'][1236414] = {name = "Warlock Hellcaller 11.2 Class Set 4pc", additional_info = "[q]Aflicción\n Lanzar Malevolencia otorga 2 acumulaciones de Crescendo atormentado y evita que Alma ennegrecida consuma acumulaciones, al tiempo que inflige daño un 25% más rápido durante 8 s.\n\nDemonología, Destrucción\n Lanzar Malevolencia otorga 2 acumulaciones de Explosión de humo y evita que Alma ennegrecida consuma acumulaciones, al tiempo que inflige daño un 15% más rápido durante 8 s."}
MultiLanguageSpellData['mx'][1236415] = {name = "Warlock Soul Harvester 11.2 Class Set 2pc", additional_info = "[q]Sombra de muerte desata tu Alma demoníaca para atacar a tu objetivo actual durante 9 s, lo que inflige ([279.306% of Spell Power]) p. de daño de las sombras y ([186.209% of Spell Power]) p. de daño de las sombras a los enemigos en un radio de 10 m con cada ataque."}
MultiLanguageSpellData['mx'][1236416] = {name = "Warlock Soul Harvester 11.2 Class Set 4pc", additional_info = "[q]El daño de Alma demoníaca aumenta un 45% y el de Estímulo malvado un 45%. Tu Alma demoníaca genera 1 fragmento de alma cada 3 s mientras ataca a los enemigos."}
MultiLanguageSpellData['mx'][1236417] = {name = "Warlock Diabolist 11.2 Class Set 2pc", additional_info = "[q]Aflicción, Destrucción\n Lanzar Descarga de caos, Lluvia de fuego o Quemadura de las Sombras invoca un oculus demoníaco, hasta un máximo de 3. Consumir Arte demoníaco lanza óculos demoníacos a tu objetivo actual que explotan e infligen ([502.813% of Spell Power]) p. de daño de fuego y ([335.172% of Spell Power]) p. de daño de fuego a los enemigos en un radio de 10 m.\n\nDemonología\n Mano de Gul'dan lanzada con máximo poder invoca un oculus demoníaco, hasta un máximo de 3. Consumir Arte demoníaco lanza óculos demoníacos a tu objetivo actual que explotan e infligen ([502.813% of Spell Power]) p. de daño de fuego y ([335.172% of Spell Power]) p. de daño de fuego a los enemigos en un radio de 10 m."}
MultiLanguageSpellData['mx'][1236418] = {name = "Warlock Diabolist 11.2 Class Set 4pc", additional_info = "[q]Óculos demoníacos analizan la batalla mientras están activos y te entregan información a medida que explotan, lo que aumenta un 2% tu intelecto durante 10 s."}
MultiLanguageSpellData['mx'][1236419] = {name = "Warrior Colossus 11.2 Class Set 2pc", additional_info = "[q]El daño de Demoler aumenta un 20% y el daño de golpe crítico de tus habilidades aumenta hasta un máximo de un 20% en objetivos afectados por tu Demoler durante 10 s, según la cantidad de acumulaciones de Poder colosal consumidas."}
MultiLanguageSpellData['mx'][1236420] = {name = "Warrior Colossus 11.2 Class Set 4pc", additional_info = "[q]Furia, Protección\n Demoler aumenta un 100% la probabilidad de golpe crítico de 1 Embate con escudo siguiente. Los golpes críticos de Embate con escudo aumentan un 80% el daño de tu Desgarrar y Heridas profundas durante 8 s.\n\nArmas\n Demoler aumenta un 100% la probabilidad de golpe crítico de 1 Golpe mortal siguiente. Los golpes críticos de Golpe mortal aumentan un 80% el daño de tu Desgarrar y Heridas profundas durante 8 s."}
