MultiLanguageSpellData['mx'][1236792] = {name = "Bomba de esencia", additional_info = "Alcance de 30 m\nInstante\n[q]Devastación\nCuando consumes Ráfaga esencial durante Llama interna, lanzas una Bomba de esencia contra tu objetivo, lo que inflige ([371% of Spell Power])p. de daño arcano a los enemigos cercanos. Este efecto se reduce cuando alcanza a más de 5 objetivos.\n\nPreservación, Aumento\nCuando consumes Ráfaga esencial durante Llama interna, lanzas una Bomba de esencia contra tu objetivo, lo que restaura ([250% of Spell Power]) p. de salud a los aliados cercanos. Este efecto se reduce cuando alcanza a más de 5 objetivos."}
MultiLanguageSpellData['mx'][1236803] = {name = "Bomba de esencia", additional_info = "Alcance de 30 m\nInstante\n[q]Devastación\nCuando consumes Ráfaga esencial durante Llama interna, lanzas una Bomba de esencia contra tu objetivo, lo que inflige ([371% of Spell Power])p. de daño arcano a los enemigos cercanos. Este efecto se reduce cuando alcanza a más de 5 objetivos.\n\nPreservación, Aumento\nCuando consumes Ráfaga esencial durante Llama interna, lanzas una Bomba de esencia contra tu objetivo, lo que restaura ([250% of Spell Power]) p. de salud a los aliados cercanos. Este efecto se reduce cuando alcanza a más de 5 objetivos."}
MultiLanguageSpellData['mx'][1236807] = {name = "Favor de dríade", additional_info = "Instante\n[q]Restauración\nCuando tu Dríade se disipa, tus siguientes 2 lanzamientos de Alivio presto sanan una cantidad equivalente al 5% de la sanación realizada mientras estaba activa y propaga un 25% de su sanación a los aliados cercanos. Este efecto se reduce cuando alcanza a más de 5 objetivos.\n\nEquilibrio, Feral, Guardián\nCuando tu Dríade se disipa, tus siguientes 2 lanzamientos de Oleada de estrellas infligen una cantidad de daño equivalente al 3% del daño infligido mientras estaba activa y propaga un 10% de su daño a los enemigos cercanos. Este efecto se reduce cuando alcanza a más de 5 objetivos."}
MultiLanguageSpellData['mx'][1236822] = {name = "Carga de sangre", additional_info = "Instante\n[q]Profano\nImposición de pena inflige un 30% más de daño y Golpe vampírico aumenta el daño de tu necrófago un 20% durante 8 s. Se pueden superponer varias aplicaciones.\n\nSangre, Escarcha\nImposición de pena inflige un 50% más de daño y Golpe vampírico aumenta el daño de tus Armas de runas danzantes un 20% durante 8 s. Se pueden superponer varias aplicaciones."}
MultiLanguageSpellData['mx'][1236824] = {name = "Núcleo alimentado", additional_info = "Alcance de 300 m\nInstante\n[q]El núcleo del taumaturgo lo protege del daño entrante. Cuando el núcleo es destruido, explota e inflige 34853 p. de daño cósmico."}
MultiLanguageSpellData['mx'][1236826] = {name = "Conjunto: Atuendo náutico de la Flota Dorada", additional_info = "Instante\n[q]Reúne las apariencias del Atuendo náutico de la Flota Dorada."}
MultiLanguageSpellData['mx'][1236835] = {name = "Núcleo agotado", additional_info = "Alcance de 300 m\nInstante\n[q]El núcleo agotado reacciona con violencia de forma periódica ante la falta de energía, lo que inflige 34853 p. de daño cósmico a todos los jugadores cada 5 s."}
MultiLanguageSpellData['mx'][1236836] = {name = "Tarjeta de memoria del Depósito de Información Segura, Contenida y Organizada", additional_info = "Rango ilimitado\nHechizo de 3 seg\n[q]Instala la tarjeta de memoria en el DISCO titánico, lo que aumenta su nivel de objeto."}
MultiLanguageSpellData['mx'][1236851] = {name = "Favor de dríade", additional_info = "Alcance de 100 m\nInstante\n[q]Restauración\nCuando tu Dríade se disipa, tus siguientes 2 lanzamientos de Alivio presto sanan una cantidad equivalente al 5% de la sanación realizada mientras estaba activa y propaga un 25% de su sanación a los aliados cercanos. Este efecto se reduce cuando alcanza a más de 5 objetivos.\n\nEquilibrio, Feral, Guardián\nCuando tu Dríade se disipa, tus siguientes 2 lanzamientos de Oleada de estrellas infligen una cantidad de daño equivalente al 3% del daño infligido mientras estaba activa y propaga un 10% de su daño a los enemigos cercanos. Este efecto se reduce cuando alcanza a más de 5 objetivos."}
