MultiLanguageSpellData['mx'][1236935] = {name = "Sobrecarga crítica", additional_info = "Instante\n[q]Tus hechizos y habilidades tienen una probabilidad de activar una Sobrecarga crítica que aumenta 31 p. tu golpe crítico cada 2 s durante 20 s."}
