MultiLanguageSpellData['mx'][1236989] = {name = "Luz de luna creciente", additional_info = "Instante\n[q]Equilibrio\nAl hacer impacto, las Oleadas de estrellas que lanza Fuego estelar se dividen y golpean a un máximo de 3 objetivos más con un 40% de efectividad y otorgan una acumulación de Luz de luna creciente. Lanzar Furia de Elune o Luna llena consume Luz de luna creciente para aumentar un 4% tu daño por cada acumulación durante 12 s.\n\nFeral, Guardián, Restauración\nAl hacer impacto, las Oleadas de estrellas que lanza Vapulear se dividen y golpean a un máximo de 3 objetivos más con un 20% de efectividad y otorgan una acumulación de Luz de luna creciente. Lanzar Haz lunar consume Luz de luna creciente para aumentar un 4% tu daño por cada acumulación durante 12 s."}
MultiLanguageSpellData['mx'][1236990] = {name = "Infusión de luz de luna", additional_info = "Instante\n[q]Equilibrio\nAl hacer impacto, las Oleadas de estrellas que lanza Fuego estelar se dividen y golpean a un máximo de 3 objetivos más con un 40% de efectividad y otorgan una acumulación de Luz de luna creciente. Lanzar Furia de Elune o Luna llena consume Luz de luna creciente para aumentar un 4% tu daño por cada acumulación durante 12 s.\n\nFeral, Guardián, Restauración\nAl hacer impacto, las Oleadas de estrellas que lanza Vapulear se dividen y golpean a un máximo de 3 objetivos más con un 20% de efectividad y otorgan una acumulación de Luz de luna creciente. Lanzar Haz lunar consume Luz de luna creciente para aumentar un 4% tu daño por cada acumulación durante 12 s."}
MultiLanguageSpellData['mx'][1236991] = {name = "Vacío devorador", additional_info = "Alcance de 100 m\nInstante\n[q]Recibir daño tiene una gran probabilidad de hacer que devores la esencia de los enemigos cercanos, lo que inflige 2116 p. de daño de las sombras dividido entre cada uno de ellos y te restaura una cantidad de salud equivalente al 150% del daño infligido.\n\n El daño fatal que no exceda 18656 p. restaura tu salud a 20% y te reconstituye como un Vacío inestable durante 6 s. Excede un 50% de salud para estabilizarte y burlar la muerte. Este efecto puede ocurrir una vez cada 8 min. El núcleo no puede infligir daño mientras se recarga."}
MultiLanguageSpellData['mx'][1236992] = {name = "Death Knight Deathbringer 11.2 Class Set 4pc", additional_info = nil}
MultiLanguageSpellData['mx'][1236993] = {name = "Escudo de energía", additional_info = "Instante\n[q]Cuando recibes daño, tienes una probabilidad de obtener un escudo de energía titánico que absorbe hasta 3662 p. de daño durante 10 s. Cuando el escudo expira, inflige daño arcano equivalente a un 30% de la absorción restante dividido entre los enemigos que están en un radio de 8 m."}
MultiLanguageSpellData['mx'][1236996] = {name = "Alma potenciada", additional_info = "Instante\n[q]Sangre, Escarcha, Profano\nExterminar inflige un 20% más de daño, y Marca de la parca se puede acumular hasta 15 veces más. Cuando explota, Marca de la parca aumenta tu probabilidad de golpe crítico un 10% durante 8 s."}
MultiLanguageSpellData['mx'][1237011] = {name = "Ola de energía", additional_info = "Rango ilimitado\nInstante\n[q]Cuando recibes daño, tienes una probabilidad de obtener un escudo de energía titánico que absorbe hasta 3662 p. de daño durante 10 s. Cuando el escudo expira, inflige daño arcano equivalente a un 30% de la absorción restante dividido entre los enemigos que están en un radio de 8 m."}
MultiLanguageSpellData['mx'][1237032] = {name = "Arma de runa danzante", additional_info = "Alcance de 30 m\nInstante\nRequiere Arma cuerpo a cuerpo\n[q]Invoca 1 copias más de Arma de runa danzante y aumenta 6 s su duración."}
MultiLanguageSpellData['mx'][1237033] = {name = "Rayo cargado", additional_info = "Rango ilimitado\nInstante\n[q]Tus hechizos y ataques tienen una probabilidad de lanzar una Descarga cargada contra tu objetivo que inflige 965 p. de daño de naturaleza divididos entre los objetivos que están en un radio de 8 m."}
MultiLanguageSpellData['mx'][1237036] = {name = "Dirigir escuadrón", additional_info = "Alcance de 40 m\nInstante\n[q]Mientras utilizas Aliento profundo y durante hasta que se cancela después, diriges a un escuadrón de 2 dracthyr que atacan a tus objetivos con Desintegrar y Golpe azur."}
