MultiLanguageSpellData['mx'][1237067] = {name = "La cacería", additional_info = "Rango ilimitado\nInstante\n[q]Velaryn marca a un jugador como presa, se abalanza sobre él y le inflige 63242239 p. de daño de caos. El efecto se reduce con cada jugador que se encuentre en el camino de La cacería .\n\n Velaryn además golpea a los jugadores que se cruza en el camino e inflige 9486336 p. de daño de caos a los jugadores en un radio de 3 m de los jugadores golpeados."}
MultiLanguageSpellData['mx'][1237068] = {name = "Aliento dimensional", additional_info = "Rango ilimitado\nHechizo de 2 seg\n[q]El alavacío dispara un rayo galáctico desde sus fauces durante 4 s que inflige 30 p. de daño cósmico a todos los jugadores afectados durante 0.3 s.\n\n Se abren varios portales, desde los cuales se emite este aliento en múltiples direcciones."}
