MultiLanguageSpellData['mx'][1241210] = {name = "Sigilo de cadenas", additional_info = "Rango ilimitado\nInstante\n[q]Ilyssa coloca un Sigilo de cadenas en la ubicación de su objetivo actual que se activa después de (5 / 2) s.\n\n Todos los jugadores son atraídos hacia el centro y frenados, lo que reduce la velocidad de movimiento un 60% durante 6 s."}
