MultiLanguageSpellData['mx'][1241241] = {name = "Escudo de energía", additional_info = "[q]Cuando recibes daño, tienes una probabilidad de obtener un escudo de energía titánico que absorbe hasta 3662 p. de daño durante 10 s. Cuando el escudo expira, inflige daño arcano equivalente a un 30% de la absorción restante dividido entre los enemigos que están en un radio de 8 m."}
