MultiLanguageSpellData['mx'][1241243] = {name = "Corriente eléctrica", additional_info = "[q]Obtienes una Corriente eléctrica al entrar en combate que aumenta 8 p. tu maestría cada 2 s hasta un máximo de (12 * 8 ) tras 24 s, y luego se restablece y se repite."}
