MultiLanguageSpellData['mx'][1245361] = {name = "Guía celestial alascuas", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Desde los pies de la colina de Khaz Modan, seguimos sus alas de ascuas encendidas, como una antorcha que surca el oscuro cielo veraniego hacia el norte\". - El peregrinaje de los primeros sabios salvajes\nPuesto de venta"}
MultiLanguageSpellData['mx'][1245370] = {name = "Zancabrisa irascible", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a tu Zancabrisa irascible.\n[q]\"Este talbuk obstinado no es fácil de montar, incluso después de conocer a su jinete. Se recomienda precaución.\"\nPuesto de venta"}
MultiLanguageSpellData['mx'][1245376] = {name = "Cazador arcano", additional_info = "Instante\n[q]Los golpes críticos de tus hechizos dañinos y habilidades de largo alcance tienen una alta probabilidad de otorgarte Cazador arcano hasta 5 veces, lo que aumenta 14 p. tu índice de golpe crítico por acumulación durante 8 s."}
MultiLanguageSpellData['mx'][1245377] = {name = "Desplegar reubicadores", additional_info = "Instante\n[q]So'azmi coloca un par de reubicadores para confundir a sus enemigos.\n Cuando un jugador toca un reubicador, se teletransporta de forma instantánea al otro reubicador idéntico."}
