MultiLanguageSpellData['mx'][1250351] = {name = "Depósito desolado", additional_info = "Alcance de 5 m\nHechizo de 2.5 seg\n[q]Los mineros que buscan fortuna en K'aresh podrían encontrar solo las escasas ofrendas de un mundo devastado. Si bien este mineral no tiene ningún uso en la artesanía algari, los habitantes de Tazavesh podrían encontrar algún valor en los escombros que puedan recolectar."}
MultiLanguageSpellData['mx'][1250356] = {name = "Depósito desolado rico", additional_info = "Alcance de 5 m\nHechizo de 2.5 seg\n[q]Los mineros que buscan fortuna en K'aresh podrían encontrar solo las escasas ofrendas de un mundo devastado. Si bien este mineral no tiene ningún uso en la artesanía algari, los habitantes de Tazavesh podrían encontrar algún valor en los escombros que puedan recolectar.\n\nA veces, emergen depósitos inusualmente grandes en la superficie. Un placer para los mineros que buscan ganarse el pan."}
