MultiLanguageSpellData['mx'][1250864] = {name = "Agregar afijo de piedra angular: Ocaso del infinito", additional_info = "Instante\n[q]Agrega el afijo Ocaso del infinito a una piedra angular mítica."}
MultiLanguageSpellData['mx'][1250865] = {name = "Agregar afijo de piedra angular: Portales del tiempo manifestados", additional_info = "Instante\n[q]Agrega el afijo Portales del tiempo manifestados a una piedra angular mítica."}
MultiLanguageSpellData['mx'][1250866] = {name = "Agregar afijo de piedra angular: Reflejos crepusculares", additional_info = "Instante\n[q]Agrega el afijo Reflejos crepusculares a una piedra angular mítica."}
MultiLanguageSpellData['mx'][1250878] = {name = "Piedra de hogar de cronoaventurero", additional_info = "Hechizo de 10 seg 30 min de reutilización\n1 carga\n[q]Te lleva de regreso a [Hearthstone Location]. Si quieres un nuevo hogar, habla con un tabernero de otro sitio."}
MultiLanguageSpellData['mx'][1250879] = {name = "Basilisco piedra ley", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Este hermoso basilisco a menudo es la presa más buscada por los cazadores debido a las propiedades mágicas que poseen sus órganos. Afortunadamente para el basilisco, su conexión con las líneas ley le permiten percibir a los depredadores cercanos.\"\nEvento de mundo:\nWoW Remix: Legion"}
MultiLanguageSpellData['mx'][1250880] = {name = "Basilisco de laja vil", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Si bien antes eran comunes en las Islas Quebradas, los basiliscos de laja vil han sido cazados intensamente por los mineros que buscan sus preciadas pieles.\"\nEvento de mundo:\nWoW Remix: Legion"}
MultiLanguageSpellData['mx'][1250881] = {name = "Basilisco aguamarina", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"A pesar del nombre, los basiliscos aguamarina se alimentan de varios cristales costeros y rocas oceánicas.\"\nEvento de mundo:\nWoW Remix: Legion"}
MultiLanguageSpellData['mx'][1250882] = {name = "Acechador nefasto illidari", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"A pesar de su debilidad por la carne y su habilidad sobrenatural de oler el miedo, estos demonios menores han sido dominados por los Illidari tal como se domestica a un compañero de caza.\"\nEvento de mundo:\nWoW Remix: Legion"}
MultiLanguageSpellData['mx'][1250884] = {name = "Acechador de añublo illidari", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Estos demonios devoran peste y se deleitan con la descomposición. ¿A quién se le ocurrió que sería una buena idea usarlos como monturas?\"\nEvento de mundo:\nWoW Remix: Legion"}
MultiLanguageSpellData['mx'][1250886] = {name = "Vetecuerno de las Tierras Altas", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"La piel de un vetecuerno de las Tierras Altas es increíblemente gruesa. No hay registro alguno de que un vetecuerno de las Tierras Altas se haya siquiera inmutado a un intento de hacerle cosquillas.\"\nEvento de mundo:\nWoW Remix: Legion"}
MultiLanguageSpellData['mx'][1250890] = {name = "Conjunto: Guardahombros del vidente trotapáramos", additional_info = "Instante\n[q]Reúne las apariencias del conjunto de armadura Placa de vidente desatado."}
MultiLanguageSpellData['mx'][1250891] = {name = "Conjunto: Capas antiguas de los reshii", additional_info = "Instante\n[q]Reúne las apariencias del conjunto de armadura Placa de vidente desatado."}
MultiLanguageSpellData['mx'][1250908] = {name = "Esencia cronodistorsionada de lenguavermis", additional_info = nil}
MultiLanguageSpellData['mx'][1250915] = {name = "Lenguavermis cronodistorsionado", additional_info = "Instante\n[q]Destemporizado, se convierte en un lenguavermis y es ignorado por la mayoría de los enemigos.\n Aumenta la velocidad de movimiento un 60%.\n\n Puede ver las motas de bronce de Argus: recoger las motas de bronce aumentará tu velocidad de movimiento y la cantidad de bronce que obtienes, lo que se acumula hasta que el efecto se termine.\n\n El combate cancela este efecto."}
