MultiLanguageSpellData['mx'][1251008] = {name = "Eclipse", additional_info = "Rango ilimitado\nInstante\n[q]Ky'veza cubre secciones de la sala con olas de oscuridad que infligen 140 p. de daño de las sombras a cualquier jugador que queda atrapado."}
MultiLanguageSpellData['mx'][1251013] = {name = "Eclipse", additional_info = "Rango ilimitado\nInstante\n[q]Ky'veza cubre secciones de la sala con olas de oscuridad que infligen 140 p. de daño de las sombras a cualquier jugador que queda atrapado."}
