MultiLanguageSpellData['mx'][1251045] = {name = "Sentencia del Vindicador", additional_info = "Alcance de 40 m\n{Instante} {1.5 min de reutilización}\n[q]Habilidad de artefacto\n\n Te conviertes en Templeluz durante 15 s e invocas un rayo de luz celestial que sigue a los objetivos, les inflige un máximo de [(200% [Attack/Spell Power])] p. de daño sagrado a los enemigos y restaura [(141% [Attack/Spell Power])] p. de salud a los objetivos aliados cada 0.5 s durante 10 s en el área. Inflige menos daño y sana menos si afecta a más de 5 objetivos.\n\nTempleluz\nPotencia los demás atributos de luz de tu artefacto."}
MultiLanguageSpellData['mx'][1251046] = {name = "Sentencia del Vindicador", additional_info = "Alcance de 100 m\nInstante\n[q]Habilidad de artefacto\n\n Te conviertes en Templeluz durante 15 s e invocas un rayo de luz celestial que sigue a los objetivos, les inflige un máximo de [(200% [Attack/Spell Power])] p. de daño sagrado a los enemigos y restaura [(141% [Attack/Spell Power])] p. de salud a los objetivos aliados cada 0.5 s durante 10 s en el área. Inflige menos daño y sana menos si afecta a más de 5 objetivos.\n\nTempleluz\nPotencia los demás atributos de luz de tu artefacto."}
