MultiLanguageSpellData['mx'][1251255] = {name = "Águila de Altamontaña copárbol", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"El águila majestuosa es un símbolo del orgullo de las tribus de Altamontaña. La capacidad de esta magnífica bestia de llevar a tauren a sus espaldas es muestra suficiente de la gran fuerza y el tamaño de las criaturas de Altamontaña.\"\nEvento de mundo:\nWoW Remix: Legion"}
MultiLanguageSpellData['mx'][1251257] = {name = "Sable de maná leygélido", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura."}
MultiLanguageSpellData['mx'][1251259] = {name = "Agregar afijo de piedra angular: Fortificación tiránica", additional_info = "Instante\n[q]Agrega el afijo Fortificación tiránica a una piedra angular mítica."}
MultiLanguageSpellData['mx'][1251264] = {name = "Sable de maná de la Fuente de la Noche", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura."}
MultiLanguageSpellData['mx'][1251265] = {name = "Sable de maná de arcabaya", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Bautizados por su parecido con las bayas brillantes que se usan en la producción de arcavino, estos felinos orgullosos poseen una aguda capacidad de detectar las líneas ley que pasan por debajo de ellos.\"\nEvento de mundo:\nWoW Remix: Legion"}
MultiLanguageSpellData['mx'][1251266] = {name = "Saeta onírica", additional_info = "Alcance de 30 mHechizo de 2 seg 3 seg de reutilización\n[q]Lanza tierra a un enemigo e inflige 150 p. de daño físico."}
MultiLanguageSpellData['mx'][1251279] = {name = "Manarraya cicatrizvil", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira una Manarraya cicatrizvil. Esta montura cambia de acuerdo con tu habilidad de equitación y tu ubicación.\n[q]\"Sobrevivir en Argus no es una tarea sencilla. Esta manarraya de piel rugosa marcada por la corrupción vil es propensa a los ataques de agresión, más de lo normal.\"\nEvento de mundo:\nWoW Remix: Legion"}
MultiLanguageSpellData['mx'][1251281] = {name = "Manarraya dientesangre", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira una Manarraya dientesangre. Esta montura cambia de acuerdo con tu habilidad de equitación y tu ubicación.\n[q]\"La destrucción de Argus despertó una sed de sangre en esta manarraya. Ahora se alimenta de la sangre corrupta de cualquier criatura en la que pueda clavarle los dientes.\"\nEvento de mundo:\nWoW Remix: Legion"}
MultiLanguageSpellData['mx'][1251283] = {name = "Manarraya albina", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira una Manarraya albina. Esta montura cambia de acuerdo con tu habilidad de equitación y tu ubicación.\n[q]\"La destrucción de Argus hizo que las manarrayas mutaran y se adaptaran a su entorno. Algunas abandonaron sus pigmentos para fortalecer sus sentidos.\"\nEvento de mundo:\nWoW Remix: Legion"}
MultiLanguageSpellData['mx'][1251284] = {name = "Manarraya luminosa", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira una Manarraya luminosa. Esta montura cambia de acuerdo con tu habilidad de equitación y tu ubicación.\n[q]\"Las manarrayas pueden emitir un brillo para atraer a su presa.\"\nEvento de mundo:\nWoW Remix: Legion"}
MultiLanguageSpellData['mx'][1251292] = {name = "Colocación", additional_info = nil}
MultiLanguageSpellData['mx'][1251295] = {name = "Corcel del crepúsculo", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Para evadir a los depredadores, este corcel atenúa su cuerno al ocultarse, y emana un brillo deslumbrante cuando se ve amenazado.\"\nEvento de mundo:\nWoW Remix: Legion"}
MultiLanguageSpellData['mx'][1251297] = {name = "Trotasol dorado", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Este espíritu libre disfruta de largos paseos a trote por la playa y de revolcarse en los campos de flores multicolor.\"\nEvento de mundo:\nWoW Remix: Legion"}
MultiLanguageSpellData['mx'][1251298] = {name = "Corcel turquesa", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Nombrado por el color particular de sus ojos que parecen penetrar en tu alma, el corcel turquesa exhibe más inteligencia que sus parientes corresueños, y es reconocido por reconocer personalidades.\"\nEvento de mundo:\nWoW Remix: Legion"}
MultiLanguageSpellData['mx'][1251300] = {name = "Pesadilla pesadumbría", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Tocada por la Pesadilla Esmeralda, la presencia de esta criatura en sueños es un presagio de desventura. Ver a una durante la vigilia es un portento de una catástrofe total.\"\nEvento de mundo:\nWoW Remix: Legion"}
MultiLanguageSpellData['mx'][1251305] = {name = "Corcel óseo del triunfo", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Un buen caballo de guerra es fiel hasta los huesos. Después de haberse desecho de su semblante mortal, este corcel es un presagio de conquista audaz.\"\nEvento de mundo:\nWoW Remix: Legion"}
MultiLanguageSpellData['mx'][1251307] = {name = "Corcel óseo de masacre", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Un buen caballo de guerra es fiel hasta los huesos. Después de haberse desecho de su semblante mortal, este corcel es un presagio de conflicto eterno.\"\nEvento de mundo:\nWoW Remix: Legion"}
MultiLanguageSpellData['mx'][1251309] = {name = "Corcel óseo de plaga", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Un buen caballo de guerra es fiel hasta los huesos. Después de haberse desecho de su semblante mortal, este corcel es un presagio de enfermedad y sufrimiento.\"\nEvento de mundo:\nWoW Remix: Legion"}
MultiLanguageSpellData['mx'][1251311] = {name = "Corcel óseo del olvido", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Un buen caballo de guerra es fiel hasta los huesos. Después de haberse desecho de su semblante mortal, este corcel es un presagio de carencia y muerte.\"\nEvento de mundo:\nWoW Remix: Legion"}
