MultiLanguageSpellData['mx'][1251395] = {name = "Ilusión: Corrupción del sha", additional_info = "Instante\n[q]Obtén la apariencia del encantamiento de arma de Corrupción del sha."}
MultiLanguageSpellData['mx'][1251396] = {name = "Talbuk azabache cuernolargo", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Los talbuks de Argus han desarrollado un pelaje abundante y grueso de colores brillantes que refleja los tintes de su planeta destruido.\"\nEvento de mundo:\nWoW Remix: Legion"}
MultiLanguageSpellData['mx'][1251397] = {name = "Zancarruinas granate", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Equipados con una gualdrapa resistente, los zancarruinas argusianos llevan a sus jinetes sin temor por los páramos devastados de Argus y más allá.\"\nEvento de mundo:\nWoW Remix: Legion"}
MultiLanguageSpellData['mx'][1251398] = {name = "Talbuk pezuñaumbría cuernolargo", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Marcados por el caos causado tras décadas de conflicto, este corcel infundido con energía vil es ideal para un aventurero intrépido.\"\nEvento de mundo:\nWoW Remix: Legion"}
MultiLanguageSpellData['mx'][1251399] = {name = "Talbuk argusiano cuernolargo", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Pocos talbuks lograron salir indemnes de la explotación de su mundo natal a manos de la Legión. Su tenacidad es propia de un corcel noble.\"\nEvento de mundo:\nWoW Remix: Legion"}
MultiLanguageSpellData['mx'][1251400] = {name = "Talbuk berilo cuernolargo", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Este talbuk salvaje que se encuentra entre las ruinas de Argus ha sobrevivido y perseverado a lo largo de décadas de conflicto.\"\nEvento de mundo:\nWoW Remix: Legion"}
