MultiLanguageSpellData['mx'][1251545] = {name = "Cosecha etérea", additional_info = "Instante\nAproximadamente 2 activaciones por minuto\n[q]Tus hechizos y habilidades que infligen daño tienen una probabilidad de concentrar energías latentes a tu alrededor para infligir daño arcano dividido entre tu objetivo y los enemigos cercanos. Los enemigos con menos del 35% de salud reciben un 20% más de daño.\n(100ms de reutilización)"}
MultiLanguageSpellData['mx'][1251549] = {name = "Reconstrucción etérea", additional_info = "Instante\nAproximadamente 2 activaciones por minuto\n[q]Tus hechizos y habilidades de apoyo tienen una probabilidad de reunir energía latente para sanar a un aliado herido. La sanación en exceso generada por este efecto otorga un escudo de absorción.\n(100ms de reutilización)"}
MultiLanguageSpellData['mx'][1251551] = {name = "Portal a Tazavesh", additional_info = nil}
MultiLanguageSpellData['mx'][1251553] = {name = "Protección etérea", additional_info = "Instante\nAproximadamente 2 activaciones por minuto\n[q]Tus hechizos y habilidades tienen una alta probabilidad de fusionar la energía a tu alrededor, lo que te otorga un escudo que reduce un 20% el daño recibido hasta un límite.\n\n Cuando tu salud cae por debajo del 40%, obtienes este efecto con un 500% de efectividad. Este efecto solo puede ocurrir una vez cada 6 min.\n(100ms de reutilización)"}
