MultiLanguageSpellData['mx'][1252004] = {name = "Apocalipsis", additional_info = "[q]Invoca la fatalidad sobre el enemigo, inflige 2% p. de daño de las sombras y hace estallar hasta 2 Heridas degenerativas sobre el objetivo.\n\n Invoca 2 necrófagos de Ejército de muertos durante 20 s.\n\nGenera 2 runas."}
MultiLanguageSpellData['mx'][1252024] = {name = "Favor de dríade", additional_info = "Instante\n[q]Restauración\nCuando tu Dríade se disipa, tus siguientes 2 lanzamientos de Alivio presto sanan una cantidad equivalente al 5% de la sanación realizada mientras estaba activa y propaga un 25% de su sanación a los aliados cercanos. Este efecto se reduce cuando alcanza a más de 5 objetivos.\n\nEquilibrio, Feral, Guardián\nCuando tu Dríade se disipa, tus siguientes 2 lanzamientos de Oleada de estrellas infligen una cantidad de daño equivalente al 3% del daño infligido mientras estaba activa y propaga un 10% de su daño a los enemigos cercanos. Este efecto se reduce cuando alcanza a más de 5 objetivos."}
