MultiLanguageSpellData['mx'][1252193] = {name = "Elegido de Odyn", additional_info = "Rango ilimitado\nInstante\n[q]Sentencia del Vindicador bendice a un máximo de 5 aliados cercanos para que los protejan las val'kyr durante 8 s.\n\n Mientras dura el efecto, las val'kyr interceptan los ataques letales y sanan al objetivo hasta que alcanza su salud máxima. No se puede activar sobre el mismo objetivo más de una vez cada 8 min."}
MultiLanguageSpellData['mx'][1252196] = {name = "Solicitar ofrenda", additional_info = "Instante\n[q]No has completado tu ofrenda al obelisco cronodistorsionado. Reduce los efectos de restauración de los obeliscos cronodistorsionados de forma significativa."}
MultiLanguageSpellData['mx'][1252198] = {name = "Órdenes empíreas", additional_info = "[q]Después de usar Sentencia del Vindicador , se vuelve Hacia la batalla .\n\nHacia la batalla\nArremete hacia adelante con un poder ferviente y castiga a todos los enemigos en tu camino con [(168% [Attack/Spell Power])] p. de daño sagrado.\n\n Se convierte en Pasaje de lazoluz después de su uso.\n\nPasaje de lazoluz\nTe adentras en un haz de luz que inflige hasta [(168% [Attack/Spell Power])] p. de daño sagrado a los enemigos y restaura hasta [(168% [Attack/Spell Power])] p. de salud a los aliados que están en un radio de 6 m, lo que te teletransporta 20 m hacia atrás o hasta alcanzar un obstáculo.\n\n Además, bajo el efecto de Templeluz , obtienes Eco de luz .\n\nEco de luz\nEmanas Luz sagrada que forma motas cada 3 s. Entrar en contacto con la mota inflige [(168% [Attack/Spell Power])] p. de daño sagrado a los enemigos cercanos o restaura [(168% [Attack/Spell Power])] p. de salud a los aliados cercanos en un radio de 60 m."}
